const webhookData = $('Webhook').first().json;
const progress = $input.first().json;

// Adaptive difficulty algorithm
const quizStats = progress.quiz_stats || {};
const avgScore = quizStats.average_score || 70;
const passed = quizStats.passed || 0;
const failed = quizStats.failed || 0;
const totalAttempts = passed + failed;

// Calculate success rate
const successRate = totalAttempts > 0 ? (passed / totalAttempts) * 100 : 50;

// Determine recommended difficulty
let recommendedDifficulty;
let difficultyScore;
let reasoning;

if (avgScore >= 90 && successRate >= 85) {
  recommendedDifficulty = 'hard';
  difficultyScore = 3;
  reasoning = 'Excellent performance - ready for advanced challenges';
} else if (avgScore >= 75 && successRate >= 70) {
  recommendedDifficulty = 'medium';
  difficultyScore = 2;
  reasoning = 'Good progress - maintaining appropriate challenge level';
} else if (avgScore >= 60 && successRate >= 50) {
  recommendedDifficulty = 'easy';
  difficultyScore = 1;
  reasoning = 'Building foundations - focusing on core concepts';
} else {
  recommendedDifficulty = 'easy';
  difficultyScore = 1;
  reasoning = 'Needs more practice - reinforcing basics';
}

// Identify areas for focus
const weaknesses = progress.weaknesses || [];
const strengths = progress.strengths || [];

// Generate personalized recommendations
const recommendations = [];
if (weaknesses.length > 0) {
  recommendations.push(`Focus on: ${weaknesses.slice(0, 2).join(', ')}`);
}
if (avgScore < 70) {
  recommendations.push('Review previous lessons before advancing');
}
if (successRate < 60 && totalAttempts > 3) {
  recommendations.push('Consider retaking recent quizzes for better understanding');
}
if (strengths.length > 0 && avgScore >= 80) {
  recommendations.push(`Ready for advanced content in: ${strengths[0]}`);
}

return {
  json: {
    success: true,
    data: {
      learner_discord_id: webhookData.body.learner_discord_id,
      recommended_difficulty: recommendedDifficulty,
      difficulty_score: difficultyScore,
      reasoning: reasoning,
      metrics: {
        average_score: Math.round(avgScore * 10) / 10,
        success_rate: Math.round(successRate * 10) / 10,
        total_attempts: totalAttempts,
        current_level: progress.level || 1
      },
      focus_areas: {
        weaknesses: weaknesses.slice(0, 3),
        strengths: strengths.slice(0, 3)
      },
      recommendations: recommendations
    },
    meta: {
      workflow: 'learning-adapt-difficulty',
      algorithm: 'v1.0',
      timestamp: new Date().toISOString()
    }
  }
};
